using Game.Shared;
using Game.Shared.Enums;
using Game.Shared.Models;

namespace Game.Server.Services;

public enum BattleActorKind { Character, Monster }
public sealed record BattleParticipant(RoomSlot Slot, Character Character);

public sealed class BattleActor
{
    public BattleParticipant? Participant { get; }
    public Monster? Monster { get; }
    public Character? Character => Participant?.Character;
    public CharacterCombatStatSnapshot? Stats { get; }
    public BattleActorKind Kind => Character is not null ? BattleActorKind.Character : BattleActorKind.Monster;
    public string ActorType => Kind.ToString();
    public int Id => Character?.Id ?? Monster!.Id;
    public int SlotIndex => Participant?.Slot.SlotIndex ?? 0;
    public string Name => Character?.Name ?? Monster!.Name;
    public string Label => Character is not null ? $"{SlotIndex}号位 {Name}" : Name;
    public int Hp { get => Character?.Hp ?? Monster!.Hp; set { if (Character is not null) Character.Hp = value; else Monster!.Hp = value; } }
    public int MaxHp => Stats?.MaxHp ?? Monster!.MaxHp;
    private BattleActor(BattleParticipant? participant, Monster? monster, CharacterCombatStatSnapshot? stats = null)
    {
        (Participant, Monster) = (participant, monster);
        Stats = participant is null ? null : stats ?? CharacterCombatStatSnapshot.Capture(participant.Character);
    }
    public static BattleActor ForCharacter(BattleParticipant participant) => new(participant, null);
    public static BattleActor ForCharacter(BattleParticipant participant, CharacterCombatStatSnapshot stats) => new(participant, null, stats);
    public static BattleActor ForMonster(Monster monster) => new(null, monster);
}

public sealed record BattleExecutionContext(Room Room, Monster Monster, IReadOnlyList<BattleParticipant> Party,
    IReadOnlyDictionary<int, ElementType> MainWeaponElements, IReadOnlyDictionary<int, OperationPotionBonuses> OperationBonuses,
    List<string> Logs, Func<Task<bool>>? InterruptIntent = null)
{
    private readonly IReadOnlyDictionary<int, CharacterCombatStatSnapshot> _characterStats = Party
        .DistinctBy(entry => entry.Character.Id).ToDictionary(entry => entry.Character.Id,
            entry => CharacterCombatStatSnapshot.Capture(entry.Character));
    public CharacterCombatStatSnapshot StatsFor(Character character) => _characterStats.TryGetValue(character.Id, out var stats)
        ? stats : CharacterCombatStatSnapshot.Capture(character);
    public BattleActor Enemy => BattleActor.ForMonster(Monster);
    public IReadOnlyList<BattleActor> Characters => Party.OrderBy(entry => entry.Slot.SlotIndex)
        .Select(entry => BattleActor.ForCharacter(entry, StatsFor(entry.Character))).ToList();
}

public sealed record BattleDamageResult(int CalculatedAmount, int ActualAmount, bool IsCritical);
public sealed record BattleEffectOutcome(BattleEffectKind Kind, BattleActor Target, bool Applied,
    int CalculatedAmount = 0, int ActualAmount = 0, bool IsCritical = false,
    RemovedBattleStatus? RemovedStatus = null, string? StatusCode = null);

public sealed class BattleSkillResult
{
    public List<BattleEffectOutcome> Outcomes { get; } = [];
    public bool UseActualDamage { get; set; }
    public bool Applied => Outcomes.Any(outcome => outcome.Applied);
    public int Damage => SumDamage(UseActualDamage);
    public int ActualDamage => SumDamage(true);
    public bool HealingOccurred => Outcomes.Any(outcome => outcome.Kind == BattleEffectKind.Heal && outcome.ActualAmount > 0);
    public bool CleansingOccurred => Outcomes.Any(outcome => outcome.Kind == BattleEffectKind.Cleanse && outcome.RemovedStatus is not null);
    private int SumDamage(bool actual) => (int)Math.Min(int.MaxValue, Outcomes.Where(outcome => outcome.Kind == BattleEffectKind.Damage)
        .Sum(outcome => (long)(actual ? outcome.ActualAmount : outcome.CalculatedAmount)));
}

public sealed class BattleCastExecution
{
    public BattleExecutionContext Battle { get; }
    public BattleSkillDefinition Skill { get; }
    public CharacterSkillDefinition? CharacterSkill => Skill as CharacterSkillDefinition;
    public BattleActor Source { get; }
    public BattleStatusSource StatusSource => new(Source.ActorType, Source.Id, Skill.Code);
    public int? ChosenTargetId { get; init; }
    public int? IntentTargetId { get; init; }
    public IReadOnlyDictionary<string, int> ProfessionLevels { get; init; } = new Dictionary<string, int>();
    public IReadOnlyList<BattleSkillCooldown> Cooldowns { get; init; } = [];
    public BattleSkillResult Result { get; } = new();
    public decimal HealthPercentAtCast { get; }
    public decimal ConditionalDamageBonus { get; set; }
    public decimal AttackPowerBonus { get; set; }
    public List<decimal> DamageMultipliers { get; } = [];
    public decimal HealingMultiplier { get; set; } = 1;
    public bool GuardCounterEligible { get; set; }
    public bool DeduplicateHealing { get; set; }
    public decimal MonsterSkillReduction { get; set; }
    public decimal MonsterSkillBonusPercent { get; set; }
    public int LegacyGuardPower { get; set; }
    public bool IsBasicAttack { get; init; }
    public Dictionary<int, int> LegacyIncomingReduction { get; } = [];
    private readonly Dictionary<BattleEffectTarget, int[]> _fixedTargets = new();
    private readonly HashSet<int> _healedTargets = [];

    public BattleCastExecution(BattleExecutionContext battle, BattleSkillDefinition skill, BattleActor source)
    {
        (Battle, Skill, Source) = (battle, skill, source);
        var stats = source.Character is { } character ? battle.StatsFor(character) : null;
        HealthPercentAtCast = stats is not null ? WeaponCombatRules.HealthDamagePercent(source.Hp,
            stats.MaxHp, stats.StaminaPercent, stats.EnmityPercent) : 0;
        foreach (var effect in skill.Effects.Where(effect => effect.TargetPolicy.FixedAtCast))
            _fixedTargets.TryAdd(effect.TargetPolicy, SelectTargets(effect, ignoreFixed: true).Select(actor => actor.Id).ToArray());
    }

    public IReadOnlyList<BattleActor> SelectTargets(BattleSkillEffect effect, bool ignoreFixed = false)
    {
        if (effect.TargetPolicy.Side == BattleTargetSide.Self) return Source.Hp > 0 ? [Source] : [];
        if (Source.Kind == BattleActorKind.Character && effect.TargetPolicy.Side == BattleTargetSide.Opponent)
            return Battle.Monster.Hp > 0 ? [Battle.Enemy] : [];
        if (Source.Kind == BattleActorKind.Monster)
        {
            var alive = Battle.Characters.Where(actor => actor.Hp > 0).ToList();
            return effect.TargetPolicy.Selection == BattleTargetSelection.AllAlive ? alive :
                alive.Where(actor => actor.Id == IntentTargetId).ToList();
        }
        var characters = Battle.Characters;
        if (!ignoreFixed && _fixedTargets.TryGetValue(effect.TargetPolicy, out var fixedIds))
            return characters.Where(actor => actor.Hp > 0 && fixedIds.Contains(actor.Id)).ToList();
        var snapshot = characters.Select(actor => new SkillBattleActor(actor.Id, actor.SlotIndex, actor.Hp, actor.MaxHp, false));
        return SkillBattlePolicy.SelectAllies(effect, snapshot, Source.Id, ChosenTargetId)
            .Select(actor => characters.Single(character => character.Id == actor.Id)).ToList();
    }

    public bool CanHeal(BattleActor actor) => !DeduplicateHealing || _healedTargets.Add(actor.Id);
}

using Game.Server.Configuration;
using Game.Server.Data;
using Game.Shared;
using Game.Shared.Dtos;
using Game.Shared.Enums;
using Game.Shared.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace Game.Server.Services;

public partial class BattleService(GameDbContext dbContext, UserService userService, ConsumableCatalog consumableCatalog, SkillCatalog skillCatalog, RewardService rewardService, DungeonRunService? dungeonRunService = null, MonsterCombatService? monsterCombatService = null, BattleLogStore? battleLogStore = null, Random? random = null, BattleMilestoneService? battleMilestones = null, WeaponCatalog? weaponCatalog = null, SoulImprintCatalog? soulImprintCatalog = null, PartyScalingService? partyScalingService = null, RoomService? roomService = null, BattleEffectExecutor? battleEffects = null, ProfessionMechanicCatalog? mechanics = null, DungeonRunRulesService? runRules = null)
{
    private readonly PartyScalingService _partyScaling = partyScalingService ?? new(dbContext, PartyScalingCatalog.Default, runRules);
    private readonly SkillBattleSnapshotFactory _skillSnapshots = new(dbContext, skillCatalog, monsterCombatService, mechanics);
    private readonly BattleEventCollector _events = battleEffects?.Events ?? monsterCombatService?.Statuses.Events ?? new();
    private BattleStatusService? _statusService;
    private BattleStatusService Statuses => _statusService ??= _effectExecutor?.Statuses ?? monsterCombatService?.Statuses ??
        new BattleStatusService(dbContext, new BattleStatusCatalog(Options.Create(new MonsterCombatOptions())), _events, mechanics, runRules);
    private BattleGuardService? _guardService;
    private BattleGuardService _guards => _guardService ??= _effectExecutor?.Guards ?? new(Statuses);
    private BattleEffectExecutor? _effectExecutor = battleEffects;
    private BattleEffectExecutor Effects => _effectExecutor ??= new(skillCatalog, Statuses, _guards,
        new BattleDamageService(Statuses, _guards, random, _events, runRules, phases: monsterCombatService?.Phases));
    private BattleRoundExecutor? _roundExecutor;
    private BattleRoundExecutor Rounds => _roundExecutor ??= new(dbContext, consumableCatalog, skillCatalog,
        Statuses, Effects, monsterCombatService, weaponCatalog, soulImprintCatalog, random, mechanics);
    private static readonly TimeSpan RoundCooldown = TimeSpan.FromSeconds(BattleRules.RoundCooldownSeconds);
    private static readonly TimeSpan AutoRoundCooldown = TimeSpan.FromSeconds(BattleRules.AutoRoundCooldownSeconds);
    private static readonly TimeSpan PreparationTimeout = TimeSpan.FromSeconds(BattleRules.PreparationTimeoutSeconds);

    public async Task<(BattleResult? Result, string? Error)> StartPreparationAsync(int roomId, string? token,
        int? expectedRoundNumber = null, int? expectedRunSequence = null)
    {
        var (room, slots, monster, user, error) = await GetBattleContextAsync(roomId, token);
        if (error is not null) return (null, error);
        var now = DateTime.UtcNow;
        if (room!.IsRepeatBattle && room.ExpiresAtUtc is DateTime deadline && now >= deadline &&
            (room.Status is RoomStatus.NotStarted or RoomStatus.Cooldown) && room.RoundNumber == 0)
        {
            await CharacterActivityManager.CloseBattleRoomAsync(dbContext, room, now);
            await SaveResultAsync(room, slots!, monster!, now, ["任务已达到时限，无法开始新一轮战斗。"]);
            return (null, "RoomClosed");
        }
        if (expectedRoundNumber.HasValue && room!.RoundNumber != expectedRoundNumber.Value ||
            expectedRunSequence.HasValue && room!.RunSequence != expectedRunSequence.Value)
            return (BuildResult(room, slots!, monster!, now, ["当前回合已经推进，本次准备请求已忽略。"]), "StaleRound");
        if (room!.Status == RoomStatus.BattleOver) return (BuildResult(room, slots!, monster!, now, ["战斗已经结束，请重置房间。"]), "BattleOver");
        if (room.Status == RoomStatus.WaveTransition) return (BuildResult(room, slots!, monster!, now, ["下一名敌人正在接近。"]), "WaveTransition");
        var isRoundCoolingDown = room.Status == RoomStatus.Cooldown && room.NextRoundAvailableAtUtc > now;

        var aliveSlots = slots!.Where(x => x.Character.Hp > 0).ToList();
        if (monster!.Hp <= 0 || aliveSlots.Count == 0)
        {
            ClearRoundState(room, slots);
            SetBattleOver(room, now);
            await Statuses.ClearRunAsync(room);
            var logs = new List<string>();
            if (aliveSlots.Count == 0) await rewardService.SettleAsync(room, false, now, logs);
            logs.Add(monster.Hp <= 0 ? "怪物已经被击败，请重置房间。" : "全队已经战败，无法继续战斗。");
            return await SaveResultAsync(room, slots, monster, now, logs);
        }

        if (!aliveSlots.Any(x => x.Slot.UserId == user!.Id)) return (null, "NoOwnedAliveCharacters");
        var clearedCharacterIds = await GetClearedCharacterIdsAsync(room.DungeonId, slots.Select(entry => entry.Character.Id).ToArray());
        if (isRoundCoolingDown)
        {
            if (aliveSlots.Where(x => x.Slot.UserId == user.Id).All(x => x.Slot.IsConfirmed))
                return (BuildResult(room, slots, monster, now, ["你的角色已经为下一回合做好准备。"]), "AlreadyPrepared");

            foreach (var entry in aliveSlots.Where(x => x.Slot.UserId == user.Id || IsSlotAuto(room, x, clearedCharacterIds, slots)))
                entry.Slot.IsConfirmed = true;
            return await SaveResultAsync(room, slots, monster, now, []);
        }

        if (room.Status != RoomStatus.Preparing)
        {
            room.Status = RoomStatus.Preparing;
            room.NextRoundAvailableAtUtc = null;
            room.RoundCooldownDurationSeconds = null;
            room.PreparationStartedAtUtc ??= now;
            room.BattleEndedAtUtc = null;
        }
        else if (aliveSlots.Where(x => x.Slot.UserId == user.Id).All(x => x.Slot.IsConfirmed))
        {
            return (BuildResult(room, slots, monster, now, ["你的角色已经准备完毕。"]), "AlreadyPrepared");
        }

        foreach (var entry in aliveSlots.Where(x => x.Slot.UserId == user.Id || IsSlotAuto(room, x, clearedCharacterIds, slots))) entry.Slot.IsConfirmed = true;
        if (aliveSlots.All(x => x.Slot.IsConfirmed)) return await ExecutePreparedRoundAsync(room, slots, monster, now, []);
        return await SaveResultAsync(room, slots, monster, now, []);
    }

    public async Task<(BattleResult? Result, string? Error)> CancelPreparationAsync(int roomId, string? token,
        int expectedRoundNumber, int expectedRunSequence)
    {
        var (room, slots, monster, user, error) = await GetBattleContextAsync(roomId, token);
        if (error is not null) return (null, error);
        var now = DateTime.UtcNow;
        if (room!.RoundNumber != expectedRoundNumber || room.RunSequence != expectedRunSequence)
            return (BuildResult(room, slots!, monster!, now, []), "StaleRound");
        if (room.Status == RoomStatus.BattleOver || monster!.Hp <= 0)
            return (BuildResult(room, slots!, monster!, now, []), "BattleOver");
        if (room.Status == RoomStatus.WaveTransition)
            return (BuildResult(room, slots!, monster!, now, []), "WaveTransition");
        var ownedAlive = slots!.Where(entry => entry.Slot.UserId == user!.Id && entry.Character.Hp > 0).ToList();
        if (ownedAlive.Count == 0) return (null, "NoOwnedAliveCharacters");
        var clearedCharacterIds = await GetClearedCharacterIdsAsync(room.DungeonId, slots.Select(entry => entry.Character.Id).ToArray());
        var manualSlots = ownedAlive.Where(entry => !IsSlotAuto(room, entry, clearedCharacterIds, slots)).ToList();
        if (manualSlots.Count == 0) return (null, "PreparationCancellationDenied");
        if (manualSlots.All(entry => !entry.Slot.IsConfirmed && !entry.Slot.IsTemporaryAuto))
            return (BuildResult(room, slots, monster!, now, []), null);
        foreach (var entry in manualSlots)
        {
            entry.Slot.IsConfirmed = false;
            entry.Slot.IsTemporaryAuto = false;
        }
        // Preserve queued actions and both deadlines. Saving the room version makes
        // cancellation race safely with the background worker's round settlement.
        return await SaveResultAsync(room, slots, monster!, now, ["已取消准备，保留已安排的技能与道具。"]);
    }

    public async Task<(BattleResult? Result, string? Error)> SyncAsync(int roomId, string? token)
    {
        var (room, slots, monster, _, error) = await GetBattleContextAsync(roomId, token);
        if (error is not null) return (null, error);
        try { await dbContext.SaveChangesAsync(); }
        catch (DbUpdateException exception) when (DatabaseWriteErrors.IsConflict(exception)) { return (null, "ConcurrencyConflict"); }
        return await SyncCoreAsync(room!, slots!, monster!);
    }

    public async Task<(BattleResult? Result, string? Error)> SyncRoomAsync(int roomId)
    {
        var (room, slots, monster, error) = await GetRoomStateAsync(roomId);
        if (error is not null) return (null, error);
        return await SyncCoreAsync(room!, slots!, monster!);
    }

    private async Task<(BattleResult? Result, string? Error)> SyncCoreAsync(Room room, List<BattleParticipant> slots, Monster monster)
    {
        var now = DateTime.UtcNow;
        if (room.ClosedAtUtc.HasValue) return (null, "RoomClosed");
        if (room.IsRepeatBattle && room.ExpiresAtUtc is DateTime deadline && now >= deadline &&
            (room.Status == RoomStatus.BattleOver ||
             (room.Status is RoomStatus.NotStarted or RoomStatus.Cooldown) && room.RoundNumber == 0))
        {
            await CharacterActivityManager.CloseBattleRoomAsync(dbContext, room, now);
            return await SaveResultAsync(room, slots, monster, now, ["任务已达到时限，本轮结束后停止重复战斗。"]);
        }
        var restartedBattle = false;
        if (room.Status == RoomStatus.BattleOver && room.IsRepeatBattle && monster.Hp <= 0 &&
            room.BattleEndedAtUtc is DateTime endedAt && now >= endedAt.AddSeconds(BattleRules.RepeatBattleDelaySeconds))
        {
            var respawnAt = endedAt.AddSeconds(BattleRules.RepeatBattleDelaySeconds);
            monster = await RunLifecycle.BeginNextRunAsync(room, slots, respawnAt, automatic: true);
            restartedBattle = true;
        }

        var aliveSlots = slots.Where(x => x.Character.Hp > 0).ToList();
        var clearedCharacterIds = await GetClearedCharacterIdsAsync(room.DungeonId, slots.Select(entry => entry.Character.Id).ToArray());
        var allAliveMembersAuto = aliveSlots.Count > 0 && aliveSlots.All(x => IsSlotAuto(room, x, clearedCharacterIds, slots));
        var stateChanged = restartedBattle;
        if (room.Status is RoomStatus.NotStarted or RoomStatus.Preparing or RoomStatus.Cooldown)
        {
            // Auto members are ready in mixed parties too. Only manual members
            // may subsequently be marked as temporary timeout attackers.
            foreach (var entry in aliveSlots.Where(entry => IsSlotAuto(room, entry, clearedCharacterIds, slots)))
            {
                if (!entry.Slot.IsConfirmed || entry.Slot.IsTemporaryAuto) stateChanged = true;
                entry.Slot.IsConfirmed = true;
                entry.Slot.IsTemporaryAuto = false;
            }
        }
        var transitionCompleted = false;
        if (room.Status == RoomStatus.Cooldown && room.NextRoundAvailableAtUtc is DateTime cooldownDeadline)
        {
            if (!allAliveMembersAuto && room.RoundCooldownDurationSeconds == BattleRules.AutoRoundCooldownSeconds)
            {
                room.RoundCooldownDurationSeconds = BattleRules.RoundCooldownSeconds;
                room.NextRoundAvailableAtUtc = cooldownDeadline.AddSeconds(
                    BattleRules.RoundCooldownSeconds - BattleRules.AutoRoundCooldownSeconds);
                stateChanged = true;
            }
            else if (allAliveMembersAuto && room.RoundCooldownDurationSeconds == BattleRules.RoundCooldownSeconds)
            {
                room.RoundCooldownDurationSeconds = BattleRules.AutoRoundCooldownSeconds;
                room.NextRoundAvailableAtUtc = cooldownDeadline.AddSeconds(
                    BattleRules.AutoRoundCooldownSeconds - BattleRules.RoundCooldownSeconds);
                stateChanged = true;
            }
        }
        if (room.Status == RoomStatus.WaveTransition && room.NextRoundAvailableAtUtc <= now)
        {
            var transitionDeadline = room.NextRoundAvailableAtUtc.Value;
            room.Status = RoomStatus.Cooldown;
            room.NextRoundAvailableAtUtc = transitionDeadline.AddSeconds(
                (allAliveMembersAuto ? BattleRules.AutoRoundCooldownSeconds : BattleRules.RoundCooldownSeconds) -
                BattleRules.WaveTransitionSeconds);
            room.RoundCooldownDurationSeconds = allAliveMembersAuto
                ? BattleRules.AutoRoundCooldownSeconds : BattleRules.RoundCooldownSeconds;
            room.PreparationStartedAtUtc = null;
            stateChanged = true;
            transitionCompleted = true;
        }
        if (room.Status == RoomStatus.Cooldown && room.NextRoundAvailableAtUtc <= now && !allAliveMembersAuto)
        {
            if (aliveSlots.Count > 0 && monster.Hp > 0 && aliveSlots.All(x => x.Slot.IsConfirmed))
            {
                room.Status = RoomStatus.Preparing;
                room.NextRoundAvailableAtUtc = null;
                room.RoundCooldownDurationSeconds = null;
                room.PreparationStartedAtUtc = now;
                return await ExecutePreparedRoundAsync(room, slots, monster, now, ["回合冷却结束，已准备的操作开始结算。"]);
            }

            room.Status = RoomStatus.NotStarted;
            room.NextRoundAvailableAtUtc = null;
            room.RoundCooldownDurationSeconds = null;
            room.PreparationStartedAtUtc = room.IsPreparationTimeoutEnabled ? now : null;
            stateChanged = true;
        }

        if (!allAliveMembersAuto && (room.Status is RoomStatus.NotStarted or RoomStatus.Preparing) &&
            aliveSlots.Count > 0 && monster.Hp > 0 && aliveSlots.All(entry => entry.Slot.IsConfirmed))
        {
            room.Status = RoomStatus.Preparing;
            return await ExecutePreparedRoundAsync(room, slots, monster, now, ["全队已准备完毕，本回合继续结算。"]);
        }
        if ((room.Status == RoomStatus.Preparing || room.Status == RoomStatus.NotStarted && !allAliveMembersAuto) &&
            room.IsPreparationTimeoutEnabled && aliveSlots.Count > 0 && monster.Hp > 0)
        {
            if (room.PreparationStartedAtUtc is null)
            {
                room.PreparationStartedAtUtc = now;
                stateChanged = true;
            }
            if (now >= room.PreparationStartedAtUtc.Value.Add(PreparationTimeout))
            {
                var logs = new List<string>();
                foreach (var entry in aliveSlots.Where(x => !x.Slot.IsConfirmed))
                {
                    entry.Slot.IsTemporaryAuto = true;
                    entry.Slot.IsConfirmed = true;
                    logs.Add($"{entry.Slot.SlotIndex}号位 {entry.Character.Name} 准备超时，本回合执行自动攻击（不释放自动技能）。");
                }
                logs.Add("准备阶段已超时，本回合自动开始。");
                return await ExecutePreparedRoundAsync(room, slots, monster, now, logs);
            }
        }
        if (room.Status == RoomStatus.Preparing)
        {
            if (aliveSlots.Count > 0 && monster.Hp > 0 && aliveSlots.All(entry => entry.Slot.IsConfirmed))
            {
                foreach (var entry in aliveSlots) entry.Slot.IsConfirmed = true;
                return await ExecutePreparedRoundAsync(room, slots, monster, now,
                    ["全队已准备完毕，本回合继续结算。"]);
            }
            return stateChanged ? await SaveResultAsync(room, slots, monster, now, []) : (BuildResult(room, slots, monster, now, []), null);
        }
        if (room.Status == RoomStatus.NotStarted && !allAliveMembersAuto)
        {
            return stateChanged
                ? await SaveResultAsync(room, slots, monster, now, restartedBattle
                    ? ["下一场副本战斗已经就绪，全队生命值已恢复。"]
                    : transitionCompleted ? [$"第 {room.CurrentWaveNumber} 波战斗已经就绪。"] : [],
                    resetLog: restartedBattle)
                : (BuildResult(room, slots, monster, now, []), null);
        }

        var autoRoundCanStart = room.Status == RoomStatus.NotStarted ||
            (room.Status == RoomStatus.Cooldown && room.NextRoundAvailableAtUtc <= now);
        if (autoRoundCanStart && aliveSlots.Count > 0 && monster.Hp > 0 && allAliveMembersAuto)
        {
            room.Status = RoomStatus.Preparing;
            room.NextRoundAvailableAtUtc = null;
            room.PreparationStartedAtUtc = now;
            foreach (var entry in aliveSlots) entry.Slot.IsConfirmed = true;
            var logs = restartedBattle
                ? new List<string> { "下一场副本战斗开始，全队生命值已恢复。", "全队均已开启自动战斗，本回合自动开始。" }
                : transitionCompleted
                    ? new List<string> { $"第 {room.CurrentWaveNumber} 波战斗开始。", "全队均已开启自动战斗，本回合自动开始。" }
                    : new List<string> { "全队均已开启自动战斗，本回合自动开始。" };
            return await ExecutePreparedRoundAsync(room, slots, monster, now, logs, resetLog: restartedBattle);
        }
        if (stateChanged)
        {
            var logs = restartedBattle
                ? new List<string> { "下一场副本战斗已经就绪，全队生命值已恢复。" }
                : transitionCompleted && allAliveMembersAuto
                    ? new List<string> { $"第 {room.CurrentWaveNumber} 波敌人已经就绪，自动战斗将在回合冷却结束后继续。" }
                    : [];
            return await SaveResultAsync(room, slots, monster, now, logs, resetLog: restartedBattle);
        }
        return (BuildResult(room, slots, monster, now, []), null);
    }

    public async Task<(BattleResult? Result, string? Error)> SetSlotAutoAsync(int roomId, SetSlotAutoRequest request, string? token)
    {
        var (room, slots, monster, user, error) = await GetBattleContextAsync(roomId, token);
        if (error is not null) return (null, error);
        var entry = slots!.SingleOrDefault(x => x.Slot.SlotIndex == request.SlotIndex);
        if (entry is null || entry.Slot.UserId != user!.Id) return (null, "AutoConfigurationDenied");
        var ownedSlots = slots.Where(slot => slot.Slot.UserId == user.Id).ToList();
        var clearedCharacterIds = await GetClearedCharacterIdsAsync(room!.DungeonId, slots.Select(member => member.Character.Id).ToArray());
        if (request.IsAutoEnabled && !ownedSlots.Any(slot => slot.Character.Hp > 0 &&
                clearedCharacterIds.Contains(slot.Character.Id))) return (null, "AutoNotUnlocked");
        var wasUserAutoEnabled = RoomAutoPolicy.IsEnabled(room, entry.Slot, slots.Select(slot => slot.Slot).ToArray());
        var wasAllAliveMembersAuto = slots.Where(slot => slot.Character.Hp > 0)
            .All(slot => IsSlotAuto(room, slot, clearedCharacterIds, slots));
        if (user.Id == room.OwnerUserId) room.IsOwnerAutoEnabled = request.IsAutoEnabled;
        foreach (var owned in ownedSlots)
        {
            owned.Slot.IsAutoEnabled = request.IsAutoEnabled;
            if (!request.IsAutoEnabled && wasUserAutoEnabled)
            {
                owned.Slot.IsConfirmed = false;
                owned.Slot.IsTemporaryAuto = false;
            }
        }
        var now = DateTime.UtcNow;
        if (request.IsAutoEnabled && room.Status is RoomStatus.NotStarted or RoomStatus.Preparing or RoomStatus.Cooldown)
            foreach (var owned in ownedSlots.Where(slot => slot.Character.Hp > 0 && clearedCharacterIds.Contains(slot.Character.Id)))
                owned.Slot.IsConfirmed = true;
        if (request.IsAutoEnabled && room!.Status == RoomStatus.NotStarted)
        {
            if (slots.Where(slot => slot.Character.Hp > 0).All(slot => IsSlotAuto(room, slot, clearedCharacterIds, slots)))
                return await SyncCoreAsync(room, slots, monster!);
        }
        if (!request.IsAutoEnabled && room!.Status == RoomStatus.Cooldown && room.NextRoundAvailableAtUtc is DateTime deadline &&
            (room.RoundCooldownDurationSeconds == BattleRules.AutoRoundCooldownSeconds ||
                room.RoundCooldownDurationSeconds is null && wasAllAliveMembersAuto))
        {
            var manualDeadline = deadline - AutoRoundCooldown + RoundCooldown;
            room.RoundCooldownDurationSeconds = BattleRules.RoundCooldownSeconds;
            if (manualDeadline <= now)
            {
                room.Status = RoomStatus.NotStarted;
                room.NextRoundAvailableAtUtc = null;
                room.RoundCooldownDurationSeconds = null;
                room.PreparationStartedAtUtc = room.IsPreparationTimeoutEnabled ? now : null;
            }
            else
            {
                room.NextRoundAvailableAtUtc = manualDeadline;
            }
        }
        if (room!.Status == RoomStatus.Preparing && request.IsAutoEnabled)
        {
            if (slots.Where(x => x.Character.Hp > 0).All(x => x.Slot.IsConfirmed))
                return await ExecutePreparedRoundAsync(room, slots, monster!, now, []);
        }

        return await SaveResultAsync(room, slots, monster!, now, []);
    }

    public async Task<(bool Success, string? Error)> QueueSkillAsync(QueueSkillRequest request, string? token)
    {
        var (room, slots, monster, user, error) = await GetBattleContextAsync(request.RoomId, token);
        if (error is not null) return (false, error);
        if (room!.Status == RoomStatus.BattleOver || monster!.Hp <= 0) return (false, "BattleOver");
        if (request.SkillSlotIndex is < 1 or > SkillRules.SlotCount) return (false, "InvalidSlotIndex");
        var participant = slots!.SingleOrDefault(entry => entry.Character.Id == request.CharacterId);
        if (participant is null || participant.Slot.UserId != user!.Id) return (false, "NotCharacterOwner");
        if (participant.Character.Hp <= 0) return (false, "CharacterDead");

        var mask = SkillRules.SlotMask(request.SkillSlotIndex);
        if (request.IsQueued)
        {
            var equipped = await dbContext.CharacterSkillSlots.SingleOrDefaultAsync(
                slot => slot.CharacterId == participant.Character.Id && slot.SlotIndex == request.SkillSlotIndex);
            var professionLevels = (await dbContext.CharacterCombatProfessions
                .Where(entry => entry.CharacterId == participant.Character.Id).ToListAsync())
                .ToDictionary(entry => entry.ProfessionCode, entry => entry.Level, StringComparer.OrdinalIgnoreCase);
            var skill = skillCatalog.Resolve(participant.Character, equipped?.SkillCode, professionLevels);
            if (skill is null)
                return (false, "SkillNotEquipped");
            var cooldown = await dbContext.BattleSkillCooldowns.SingleOrDefaultAsync(entry =>
                entry.RoomId == room.Id && entry.CharacterId == participant.Character.Id && entry.SkillCode == skill.Code);
            if ((cooldown?.ReadyAtRound ?? skill.InitialCooldownRounds) > room.RoundNumber)
                return (false, "SkillCooldown");
            if (request.TargetCharacterId.HasValue &&
                (!SkillBattlePolicy.CanChooseAllyTarget(skill) ||
                 !slots!.Any(entry => entry.Character.Id == request.TargetCharacterId && entry.Character.Hp > 0)))
                return (false, "InvalidSkillTarget");
            if (!await CanSkillApplyAsync(room, monster, skill, participant, slots!, request.TargetCharacterId))
                return (false, "NoValidSkillTarget");
            SkillQueueRules.Queue(participant.Slot, request.SkillSlotIndex, request.TargetCharacterId);
        }
        else SkillQueueRules.Clear(participant.Slot, mask);

        room.Version++;
        return await SaveAsync();
    }

    public async Task<(bool Success, string? Error)> QueueSoulImprintAsync(QueueSoulImprintRequest request, string? token)
    {
        var (room, slots, monster, user, error) = await GetBattleContextAsync(request.RoomId, token);
        if (error is not null) return (false, error);
        if (room!.Status == RoomStatus.BattleOver || monster!.Hp <= 0) return (false, "BattleOver");
        var participant = slots!.SingleOrDefault(entry => entry.Character.Id == request.CharacterId);
        if (participant is null || participant.Slot.UserId != user!.Id) return (false, "NotCharacterOwner");
        if (participant.Character.Hp <= 0) return (false, "CharacterDead");
        if (request.IsQueued)
        {
            if (soulImprintCatalog is null) return (false, "SoulImprintNotEquipped");
            var equipped = await dbContext.CharacterSoulImprints.SingleOrDefaultAsync(entry =>
                entry.CharacterId == request.CharacterId && entry.EquippedSlotIndex == SoulImprintRules.SlotIndex);
            var definition = soulImprintCatalog.Find(equipped?.SoulImprintCode);
            if (definition is null) return (false, "SoulImprintNotEquipped");
            var cooldown = await dbContext.BattleSkillCooldowns.SingleOrDefaultAsync(entry =>
                entry.RoomId == room.Id && entry.CharacterId == request.CharacterId &&
                entry.SkillCode == SoulImprintRules.CooldownCode(definition.Code));
            var readyAtRound = cooldown?.ReadyAtRound ?? definition.InitialCooldownRounds;
            if (readyAtRound > room.RoundNumber) return (false, "SoulImprintCooldown");
            if (!await Rounds.CanSoulImprintApplyAsync(room, monster, definition, participant, slots))
                return (false, "NoValidSoulImprintTarget");
        }
        participant.Slot.IsSoulImprintQueued = request.IsQueued;
        room.Version++;
        return await SaveAsync();
    }

    public async Task<(BattleResult? Result, string? Error)> ExecuteRoundAsync(int roomId, string? token)
    {
        var (room, slots, monster, _, error) = await GetBattleContextAsync(roomId, token);
        if (error is not null) return (null, error);
        var now = DateTime.UtcNow;
        if (room!.Status != RoomStatus.Preparing || slots!.Where(x => x.Character.Hp > 0).Any(x => !x.Slot.IsConfirmed)) return (BuildResult(room, slots, monster!, now, ["所有存活角色准备完毕后才能执行本回合。"]), "PreparationRequired");
        return await ExecutePreparedRoundAsync(room, slots, monster!, now, []);
    }

    public Task<(BattleResult? Result, string? Error)> ExecuteBattleAsync(int roomId, string? token) => ExecuteRoundAsync(roomId, token);

    public async Task<(bool Success, string? Error)> ResetBattleAsync(int roomId, string? token)
    {
        var (room, slots, monster, user, error) = await GetBattleContextAsync(roomId, token);
        if (error is not null) return (false, error);
        if (room!.OwnerUserId != user!.Id) return (false, "NotOwner");
        if (room.Status != RoomStatus.BattleOver) return (false, "BattleNotOver");
        if (room.ClosedAtUtc.HasValue) return (false, "RoomClosed");
        if (room.IsRepeatBattle && monster!.Hp <= 0) return (false, "RepeatBattlePending");
        await RunLifecycle.BeginNextRunAsync(room, slots!, DateTime.UtcNow, automatic: false);
        room.Version++;
        var save = await SaveAsync();
        if (save.Success) battleLogStore?.Clear(room.Id);
        return save;
    }

    private async Task<(BattleResult? Result, string? Error)> ExecutePreparedRoundAsync(Room room, List<BattleParticipant> slots, Monster monster, DateTime now, List<string> logs, bool resetLog = false)
    {
        var aliveSlots = slots.Where(x => x.Character.Hp > 0).OrderBy(x => x.Slot.SlotIndex).ToList();
        if (aliveSlots.Count == 0 || aliveSlots.Any(x => !x.Slot.IsConfirmed)) return (null, "PreparationRequired");
        await _partyScaling.SynchronizeAsync(room, slots.Select(entry => entry.Slot).ToList());
        var clearedCharacterIds = await GetClearedCharacterIdsAsync(room.DungeonId, slots.Select(entry => entry.Character.Id).ToArray());
        foreach (var entry in aliveSlots)
        {
            entry.Slot.HasParticipatedInRun = true;
            entry.Slot.LastParticipatedMonsterId = monster.Id;
        }
        await rewardService.CaptureDungeonParticipantsAsync(room, aliveSlots.Select(entry => entry.Character.Id));
        // The scope spans calculation, wave/reward changes and the one atomic save.
        using var statusSettlement = await Statuses.BeginSettlementAsync(room);
        using var recording = _events.Begin(room, monster, slots.OrderBy(entry => entry.Slot.SlotIndex).ToList());
        var autoCharacterIds = aliveSlots.Where(entry => !entry.Slot.IsTemporaryAuto &&
            IsSlotAuto(room, entry, clearedCharacterIds, slots)).Select(entry => entry.Character.Id).ToHashSet();
        var outcome = await Rounds.ExecuteAsync(room, monster, slots, autoCharacterIds, logs);
        if (outcome == BattleRoundOutcome.MonsterDefeated)
        {
            var participants = slots.Where(slot => slot.Slot.UserId.HasValue)
                .Select(slot => new RewardParticipant(slot.Slot.UserId!.Value, slot.Character)).ToList();
            var advance = await GetDungeonRunService().AdvanceAfterDefeatAsync(room, monster, participants, now, logs,
                slots.Where(slot => slot.Slot.LastParticipatedMonsterId == monster.Id).Select(slot => slot.Character.Id).ToList(),
                slots.Where(slot => slot.Slot.HasParticipatedInRun).Select(slot => slot.Character.Id).ToList());
            if (advance.Error is not null) return (null, advance.Error);
            monster = advance.ActiveMonster;
        }
        else if (outcome == BattleRoundOutcome.PartyDefeated)
        {
            SetBattleOver(room, now);
            await rewardService.SettleAsync(room, false, now, logs);
            logs.Add("全队已战败。");
        }
        else
        {
            room.Status = RoomStatus.Cooldown;
            room.RoundCooldownDurationSeconds = slots.Where(slot => slot.Character.Hp > 0)
                .All(slot => IsSlotAuto(room, slot, clearedCharacterIds, slots))
                ? BattleRules.AutoRoundCooldownSeconds : BattleRules.RoundCooldownSeconds;
            room.NextRoundAvailableAtUtc = now.AddSeconds(room.RoundCooldownDurationSeconds.Value);
            room.BattleEndedAtUtc = null;
        }
        await Rounds.FinishRoundEffectsAsync(room, slots);
        if (room.Status == RoomStatus.BattleOver) await Statuses.ClearRunAsync(room);
        room.RoundNumber++;
        await Rounds.UpdateTemporaryWeaponBonusesAsync(room, slots);
        ClearRoundState(room, slots);
        if (room.IsRepeatBattle && room.Status == RoomStatus.BattleOver &&
            (monster.Hp > 0 || room.ExpiresAtUtc is DateTime deadline && now >= deadline))
        {
            await CharacterActivityManager.CloseBattleRoomAsync(dbContext, room, now);
            logs.Add(monster.Hp > 0 ? "队伍战败，重复战斗已停止。" : "任务已达到时限，本轮结算后停止重复战斗。");
        }
        if (monsterCombatService is not null && room.Status != RoomStatus.BattleOver && monster.Hp > 0)
            await monsterCombatService.EnsureIntentAsync(room, monster);
        return await SaveResultAsync(room, slots, monster, now, logs, resetLog);
    }

    private async Task<bool> CanSkillApplyAsync(Room room, Monster monster, CharacterSkillDefinition skill,
        BattleParticipant participant, IReadOnlyList<BattleParticipant> slots, int? chosenTargetId = null)
    {
        var snapshot = await _skillSnapshots.CaptureAsync(room, monster, skill, participant.Character.Id,
            slots.Select(entry => (entry.Slot, entry.Character)));
        return SkillBattlePolicy.HasApplicableEffect(skill, snapshot, chosenTargetId);
    }

    private async Task<(BattleResult? Result, string? Error)> SaveResultAsync(Room room, List<BattleParticipant> slots, Monster monster, DateTime now, List<string> logs, bool resetLog = false)
    {
        room.Version++;
        var save = await SaveAsync();
        if (!save.Success) return (null, save.Error);
        var events = _events.Snapshot(room);
        var published = resetLog ? battleLogStore?.Replace(room.Id, logs, now, events) : battleLogStore?.Append(room.Id, logs, now, events);
        var result = BuildResult(room, slots, monster, now, logs);
        result.Events = published ?? events;
        result.BattleHistoryEpoch = battleLogStore?.Epoch ?? "";
        return (result, null);
    }
    private async Task<(bool Success, string? Error)> SaveAsync()
    {
        dbContext.ChangeTracker.DetectChanges();
        foreach (var entry in dbContext.ChangeTracker.Entries<Character>().Where(entry => entry.State == EntityState.Modified))
            entry.Entity.Version++;
        try
        {
            await dbContext.SaveChangesAsync();
            return (true, null);
        }
        catch (DbUpdateException exception) when (DatabaseWriteErrors.IsConflict(exception))
        {
            dbContext.ChangeTracker.Clear();
            return (false, "ConcurrencyConflict");
        }
    }
    private static bool IsSlotAuto(Room room, BattleParticipant entry, IReadOnlyCollection<int> clearedCharacterIds,
        IReadOnlyCollection<BattleParticipant> slots) =>
        RoomAutoPolicy.IsAuto(room, entry.Slot, clearedCharacterIds, slots.Select(item => item.Slot).ToArray());

    private async Task<List<int>> GetClearedCharacterIdsAsync(int dungeonId, IReadOnlyCollection<int> characterIds)
    {
        if (characterIds.Count == 0) return [];
        var dungeonCode = await dbContext.Dungeons.Where(dungeon => dungeon.Id == dungeonId)
            .Select(dungeon => dungeon.Code).SingleAsync();
        return await dbContext.CharacterBattleMilestones.Where(milestone =>
            characterIds.Contains(milestone.CharacterId) && milestone.Kind == BattleMilestoneService.DungeonClearKind &&
            milestone.TargetCode == dungeonCode && milestone.Count > 0)
            .Select(milestone => milestone.CharacterId).ToListAsync();
    }

    private static void ClearRoundState(Room room, IEnumerable<BattleParticipant> slots) => DungeonRunLifecycleService.ClearRoundState(room, slots);
    private static void SetBattleOver(Room room, DateTime now) { room.Status = RoomStatus.BattleOver; room.NextRoundAvailableAtUtc = null; room.RoundCooldownDurationSeconds = null; room.PreparationStartedAtUtc = null; room.BattleEndedAtUtc = now; }
    private DungeonRunService GetDungeonRunService() => dungeonRunService ?? new DungeonRunService(dbContext, rewardService, monsterCombatService, battleMilestones, runRules: runRules);
    private DungeonRunLifecycleService RunLifecycle => new(dbContext, GetDungeonRunService(), _partyScaling, monsterCombatService, runRules);
    private static BattleResult BuildResult(Room room, List<BattleParticipant> slots, Monster monster, DateTime now, List<string> logs) => new() { RoomId = room.Id, CharacterHp = slots.OrderBy(x => x.Slot.SlotIndex).FirstOrDefault()?.Character.Hp ?? 0, CharacterMaxHp = slots.OrderBy(x => x.Slot.SlotIndex).Select(x => TalentRules.EffectiveMaxHp(x.Character)).FirstOrDefault(), MonsterHp = monster.Hp, MonsterMaxHp = monster.MaxHp, CurrentWaveNumber = room.CurrentWaveNumber, TotalWaveCount = room.TotalWaveCount, RoomStatus = room.Status, NextRoundAvailableAtUtc = room.NextRoundAvailableAtUtc, BattleEndedAtUtc = room.BattleEndedAtUtc, ServerTimeUtc = now, CanExecuteRound = room.Status == RoomStatus.Preparing && slots.Where(x => x.Character.Hp > 0).All(x => x.Slot.IsConfirmed) && monster.Hp > 0, IsVictory = room.Status == RoomStatus.BattleOver && monster.Hp <= 0, IsCharacterDead = !slots.Any(x => x.Character.Hp > 0), Logs = logs };

    private async Task<(Room? Room, List<BattleParticipant>? Slots, Monster? Monster, User? User, string? Error)> GetBattleContextAsync(int roomId, string? token)
    {
        var (room, slots, monster, roomError) = await GetRoomStateAsync(roomId);
        if (roomError is not null) return (room, slots, monster, null, roomError);
        if (room!.ClosedAtUtc.HasValue) return (room, slots, monster, null, "RoomClosed");
        var (user, error) = await userService.GetCurrentUserEntityAsync(token);
        if (error is not null) return (room, null, null, null, error);
        if (!slots!.Any(x => x.Slot.UserId == user!.Id)) return (room, null, null, user, "NotInRoom");
        var seenAt = DateTime.UtcNow;
        var ownSlots = slots.Where(entry => entry.Slot.UserId == user.Id).ToList();
        if (ownSlots.Any(entry => RoomAutoPolicy.IsOffline(room, entry.Slot, seenAt))) room.Version++;
        foreach (var slot in ownSlots)
            slot.Slot.LastSeenAtUtc = seenAt;
        return (room, slots, monster, user, null);
    }

    private async Task<(Room? Room, List<BattleParticipant>? Slots, Monster? Monster, string? Error)> GetRoomStateAsync(int roomId)
    {
        // Apply reservations before reading the party and before an automatic restart or round.
        if (roomService is not null) await roomService.ProcessPendingOperationsAsync(roomId);
        var room = await dbContext.Rooms.FirstOrDefaultAsync(x => x.Id == roomId);
        if (room is null) return (null, null, null, "NotFound");
        var slotRows = await dbContext.RoomSlots.Where(x => x.RoomId == roomId && x.CharacterId.HasValue).OrderBy(x => x.SlotIndex).ToListAsync();
        var ids = slotRows.Select(x => x.CharacterId!.Value).ToList();
        var characters = await dbContext.Characters.Where(x => ids.Contains(x.Id)).ToDictionaryAsync(x => x.Id);
        var slots = slotRows.Where(x => characters.ContainsKey(x.CharacterId!.Value)).Select(x => new BattleParticipant(x, characters[x.CharacterId!.Value])).ToList();
        var monster = await dbContext.Monsters.FindAsync(room.MonsterId);
        return monster is null ? (room, slots, null, "MonsterNotFound") : (room, slots, monster, null);
    }
}

using Game.Server.Configuration;
using Game.Server.Data;
using Game.Shared;
using Game.Shared.Dtos;
using Game.Shared.Enums;
using Game.Shared.Models;
using Microsoft.EntityFrameworkCore;

namespace Game.Server.Services;

public readonly record struct BattleStatusSource(string ActorType, int ActorId, string? SkillCode = null);

/// <summary>
/// Owns status instances for both sides. It stages changes in the caller's battle transaction;
/// applying, consuming or displaying a status never saves the database independently.
/// </summary>
public sealed class BattleStatusService(GameDbContext db, BattleStatusCatalog catalog, BattleEventCollector? events = null,
    ProfessionMechanicCatalog? mechanics = null, DungeonRunRulesService? runRules = null)
{
    private readonly ProfessionMechanicDescription _mechanicDescriptions = new(mechanics ?? ProfessionMechanicCatalog.Default);
    public BattleStatusCatalog Catalog => catalog;
    public const string ActionSkippedCode = "round-action-skipped";

    public async Task<bool> IsActionBlockedAsync(Room room, int characterId) =>
        await ModifierAsync(room, "Character", characterId, "ActionBlocked") > 0 ||
        await HasAsync(room, "Character", characterId, ActionSkippedCode);

    public async Task<bool> SkipBlockedActionAsync(Room room, int characterId)
    {
        if (!await IsActionBlockedAsync(room, characterId)) return false;
        if (!await HasAsync(room, "Character", characterId, ActionSkippedCode))
            await ApplyAsync(room, "Character", characterId, ActionSkippedCode, 0, [], "");
        return true;
    }

    public async Task<int> IncreaseStacksAsync(Room room, string targetType, int targetId, string code, int count)
    {
        if (count <= 0) throw new ArgumentOutOfRangeException(nameof(count));
        var effect = (await GetActiveAsync(room, targetType, [targetId])).FirstOrDefault(s => s.EffectCode == code);
        if (effect is null) return 0;
        var before = effect.Stacks;
        effect.Stacks = Math.Min(CatalogFor(room).Find(code)!.MaxStacks, effect.Stacks + count);
        if (effect.Stacks != before) CaptureStatus(room, effect, BattleStatusChange.Refreshed, before, effect.Stacks);
        return effect.Stacks;
    }
    public BattleStatusCatalog CatalogFor(Room room) => runRules?.CombatFor(room).Statuses ?? catalog;
    public async Task PrepareAsync(Room room)
    {
        if (runRules is not null) await runRules.EnsureAsync(room);
    }
    public BattleEventCollector Events { get; } = events ?? new();
    private SettlementScope? _settlement;
    private ReadSnapshotScope? _readSnapshot;

    /// <summary>Captures one request's display state without tracking new status entities.</summary>
    public async Task<IDisposable> BeginReadSnapshotAsync(Room room)
    {
        await PrepareAsync(room);
        if (_readSnapshot is not null) throw new InvalidOperationException("A battle status read snapshot is already active.");
        var effects = SettlementStates(room);
        if (effects is null)
        {
            effects = await db.BattleStatusEffects.AsNoTracking().Where(effect => effect.RoomId == room.Id &&
                effect.RunSequence == room.RunSequence && effect.ExpiresAfterRound >= room.RoundNumber).ToListAsync();
            var byKey = effects.ToDictionary(effect => (effect.TargetType, effect.TargetId, effect.EffectCode));
            foreach (var entry in db.ChangeTracker.Entries<BattleStatusEffect>().Where(entry =>
                         entry.Entity.RoomId == room.Id && entry.Entity.RunSequence == room.RunSequence))
            {
                var effect = entry.Entity;
                var key = (effect.TargetType, effect.TargetId, effect.EffectCode);
                if (entry.State == EntityState.Deleted || effect.ExpiresAfterRound < room.RoundNumber) byKey.Remove(key);
                else byKey[key] = (BattleStatusEffect)entry.CurrentValues.ToObject();
            }
            effects = byKey.Values.ToList();
        }
        var monsterIds = effects.Where(effect => effect.ExpiresAfterRound >= room.RoundNumber &&
                effect.BoundTargetType == "Monster" && effect.BoundTargetId.HasValue)
            .Select(effect => effect.BoundTargetId!.Value).Distinct().ToArray();
        var names = monsterIds.Length == 0 ? new Dictionary<int, string>() : await db.Monsters.AsNoTracking()
            .Where(monster => monsterIds.Contains(monster.Id)).Select(monster => new { monster.Id, monster.Name })
            .ToDictionaryAsync(monster => monster.Id, monster => monster.Name);
        var scope = new ReadSnapshotScope(this, room.Id, room.RunSequence, effects, names);
        _readSnapshot = scope;
        return scope;
    }

    private sealed class ReadSnapshotScope(BattleStatusService owner, int roomId, int runSequence,
        List<BattleStatusEffect> effects, Dictionary<int, string> monsterNames) : IDisposable
    {
        public int RoomId { get; } = roomId;
        public int RunSequence { get; } = runSequence;
        public List<BattleStatusEffect> Effects { get; } = effects;
        public Dictionary<int, string> MonsterNames { get; } = monsterNames;
        public void Dispose()
        {
            if (ReferenceEquals(owner._readSnapshot, this)) owner._readSnapshot = null;
        }
    }

    private ReadSnapshotScope? ReadSnapshot(Room room) => _readSnapshot is { } scope &&
        scope.RoomId == room.Id && scope.RunSequence == room.RunSequence ? scope : null;

    /// <summary>
    /// Loads this challenge once for a settlement. The tracked entities remain authoritative,
    /// including unsaved changes; disposal must cover both successful and failed commits.
    /// Clearing the change tracker aborts the settlement; dispose before further status calls.
    /// </summary>
    public async Task<IDisposable> BeginSettlementAsync(Room room)
    {
        await PrepareAsync(room);
        if (_settlement is not null) throw new InvalidOperationException("A battle status settlement is already active.");
        var scope = new SettlementScope(this, room.Id, room.RunSequence);
        _settlement = scope;
        try
        {
            // Include expired rows so refreshing their unique key reuses the existing instance.
            scope.Effects.AddRange(await db.BattleStatusEffects.Where(effect => effect.RoomId == scope.RoomId &&
                effect.RunSequence == scope.RunSequence).ToListAsync());
            scope.IsLoaded = true;
            return scope;
        }
        catch
        {
            scope.Dispose();
            throw;
        }
    }

    private List<BattleStatusEffect>? SettlementStates(Room room)
    {
        if (_settlement is not { } scope || scope.RoomId != room.Id || scope.RunSequence != room.RunSequence) return null;
        if (!scope.IsLoaded) throw new InvalidOperationException("Battle statuses are still loading.");
        // Keep deleted persisted instances for reapplication before saving. Added-then-removed
        // instances become detached and must not be resurrected as existing database rows.
        scope.Effects.RemoveAll(effect => db.Entry(effect).State == EntityState.Detached);
        foreach (var local in db.BattleStatusEffects.Local.Where(effect => effect.RoomId == scope.RoomId &&
                     effect.RunSequence == scope.RunSequence))
            if (!scope.Effects.Contains(local)) scope.Effects.Add(local);
        return scope.Effects;
    }

    private sealed class SettlementScope(BattleStatusService owner, int roomId, int runSequence) : IDisposable
    {
        public int RoomId { get; } = roomId;
        public int RunSequence { get; } = runSequence;
        public List<BattleStatusEffect> Effects { get; } = [];
        public bool IsLoaded { get; set; }
        public void Dispose()
        {
            if (ReferenceEquals(owner._settlement, this)) owner._settlement = null;
        }
    }

    public Task<List<BattleStatusEffect>> MechanicStatesAsync(Room room, string actorType, int actorId, BattleStatusMechanic mechanic) =>
        FindMechanicStatesAsync(room, actorType, actorId, mechanic);

    private async Task<List<BattleStatusEffect>> FindMechanicStatesAsync(Room room, string actorType, int actorId, BattleStatusMechanic mechanic) =>
        (await GetActiveAsync(room, actorType, [actorId])).Where(effect => CatalogFor(room).Find(effect.EffectCode)?.Mechanic == mechanic).ToList();

    public async Task<decimal> MechanicPowerAsync(Room room, string actorType, int actorId, BattleStatusMechanic mechanic) =>
        (await FindMechanicStatesAsync(room, actorType, actorId, mechanic)).Select(effect =>
            Math.Abs(effect.MagnitudeSnapshot ?? CatalogFor(room).Find(effect.EffectCode)!.FamilyStrength)).DefaultIfEmpty(0).Max();

    public async Task<decimal> ConsumeMechanicPowerAsync(Room room, string actorType, int actorId, BattleStatusMechanic mechanic)
    {
        var effects = await FindMechanicStatesAsync(room, actorType, actorId, mechanic);
        var power = effects.Select(effect => Math.Abs(effect.MagnitudeSnapshot ?? CatalogFor(room).Find(effect.EffectCode)!.FamilyStrength)).DefaultIfEmpty(0).Max();
        RemoveStates(room, effects, BattleStatusChange.Consumed);
        return power;
    }
    public async Task<List<BattleStatusEffect>> GetActiveAsync(Room room, string targetType,
        IReadOnlyCollection<int> targetIds)
    {
        await PrepareAsync(room);
        if (SettlementStates(room) is { } loaded)
            return loaded.Where(effect => effect.TargetType == targetType && targetIds.Contains(effect.TargetId) &&
                effect.ExpiresAfterRound >= room.RoundNumber && db.Entry(effect).State != EntityState.Deleted).ToList();
        if (ReadSnapshot(room) is { } snapshot)
            return snapshot.Effects.Where(effect => effect.TargetType == targetType && targetIds.Contains(effect.TargetId) &&
                effect.ExpiresAfterRound >= room.RoundNumber).ToList();
        var effects = await db.BattleStatusEffects.Where(effect => effect.RoomId == room.Id &&
            effect.RunSequence == room.RunSequence && effect.TargetType == targetType &&
            targetIds.Contains(effect.TargetId) && effect.ExpiresAfterRound >= room.RoundNumber).ToListAsync();
        effects.RemoveAll(effect => db.Entry(effect).State == EntityState.Deleted || effect.ExpiresAfterRound < room.RoundNumber);
        foreach (var local in db.BattleStatusEffects.Local.Where(effect => effect.RoomId == room.Id &&
                     effect.RunSequence == room.RunSequence && effect.TargetType == targetType &&
                     targetIds.Contains(effect.TargetId) && effect.ExpiresAfterRound >= room.RoundNumber &&
                     db.Entry(effect).State != EntityState.Deleted))
            if (!effects.Contains(local)) effects.Add(local);
        return effects;
    }

    public async Task<bool> HasAsync(Room room, string targetType, int targetId, string code) =>
        (await GetActiveAsync(room, targetType, [targetId])).Any(effect =>
            string.Equals(effect.EffectCode, code, StringComparison.OrdinalIgnoreCase));

    public async Task<int> StacksAsync(Room room, string targetType, int targetId, string code) =>
        (await GetActiveAsync(room, targetType, [targetId])).FirstOrDefault(effect =>
            string.Equals(effect.EffectCode, code, StringComparison.OrdinalIgnoreCase))?.Stacks ?? 0;

    public async Task<bool> HasRemovableAsync(Room room, string targetType,
        IReadOnlyCollection<int> targetIds, bool positive) =>
        (await GetActiveAsync(room, targetType, targetIds)).Any(effect => IsRemovable(room, effect, positive));

    public bool IsRemovable(BattleStatusEffect effect, bool positive) =>
        catalog.Find(effect.EffectCode) is { } definition && definition.IsPositive == positive && definition.IsDispellable;

    public bool IsRemovable(Room room, BattleStatusEffect effect, bool positive) =>
        CatalogFor(room).Find(effect.EffectCode) is { } definition && definition.IsPositive == positive && definition.IsDispellable;

    public async Task RemoveAsync(Room room, string targetType, int targetId, string code)
    {
        RemoveStates(room, (await GetActiveAsync(room, targetType, [targetId]))
            .Where(effect => string.Equals(effect.EffectCode, code, StringComparison.OrdinalIgnoreCase)), BattleStatusChange.Removed);
    }

    public async Task RemoveCodesAsync(Room room, string targetType, IReadOnlyCollection<int> targetIds,
        IReadOnlyCollection<string> codes) => RemoveStates(room,
            (await GetActiveAsync(room, targetType, targetIds)).Where(effect => codes.Contains(effect.EffectCode)), BattleStatusChange.Expired);

    public async Task<RemovedBattleStatus?> RemoveFirstAsync(Room room, string targetType,
        IReadOnlyList<int> targetIds, bool positive)
    {
        var order = targetIds.Select((id, index) => (id, index)).ToDictionary(entry => entry.id, entry => entry.index);
        var effect = (await GetActiveAsync(room, targetType, targetIds))
            .OrderBy(effect => order.GetValueOrDefault(effect.TargetId, int.MaxValue))
            .ThenBy(effect => !positive && CatalogFor(room).Find(effect.EffectCode)?.Mechanic == BattleStatusMechanic.PlaguePoison ? 0 : 1)
            .ThenBy(effect => effect.Id)
            .FirstOrDefault(effect => CatalogFor(room).Find(effect.EffectCode) is { } definition &&
                definition.IsPositive == positive && definition.IsDispellable);
        if (effect is null) return null;
        var definition = CatalogFor(room).Find(effect.EffectCode)!;
        CaptureStatus(room, effect, BattleStatusChange.Removed, effect.Stacks, 0,
            positive ? BattleEventKind.Dispel : BattleEventKind.Cleanse);
        db.BattleStatusEffects.Remove(effect);
        return new(effect.TargetId, definition.Code, definition.Name, definition.IsPositive);
    }

    public async Task<decimal> ModifierAsync(Room room, string targetType, int targetId, string effectType) =>
        (await GetActiveAsync(room, targetType, [targetId])).Sum(effect =>
            CatalogFor(room).Find(effect.EffectCode) is { } definition && definition.EffectType == effectType
                ? (effect.MagnitudeSnapshot ?? definition.ValuePerStack) * effect.Stacks : 0m);

    public async Task<bool> ApplyAsync(Room room, string targetType, int targetId, string code,
        int durationRounds, List<string> logs, string targetLabel, int? perTickValue = null,
        BattleStatusSource? source = null, string? boundTargetType = null, int? boundTargetId = null,
        decimal? magnitudeSnapshot = null, int? counterCount = null)
    {
        await PrepareAsync(room);
        var definition = CatalogFor(room).Find(code);
        if (definition is null) return false;
        if (counterCount.HasValue && (counterCount < 1 || counterCount > definition.MaxStacks)) throw new ArgumentOutOfRangeException(nameof(counterCount));
        if (perTickValue is <= 0) throw new ArgumentOutOfRangeException(nameof(perTickValue));
        if (durationRounds < 0)
            throw new ArgumentOutOfRangeException(nameof(durationRounds));
        if ((boundTargetType is null) != (boundTargetId is null))
            throw new ArgumentException("A bound target needs both its actor type and identity.");
        if (targetType is not ("Character" or "Monster") || targetId <= 0 ||
            source is { } origin && (origin.ActorType is not ("Character" or "Monster") || origin.ActorId <= 0) ||
            boundTargetType is not null && (boundTargetType is not ("Character" or "Monster") || boundTargetId <= 0))
            throw new ArgumentException("A battle status needs valid actor identities.");

        if (definition.FamilyCode is not null)
        {
            var family = (await GetActiveAsync(room, targetType, [targetId])).Where(entry =>
                CatalogFor(room).Find(entry.EffectCode)?.FamilyCode == definition.FamilyCode).ToList();
            var stronger = family.OrderByDescending(entry => Math.Abs(entry.MagnitudeSnapshot ?? CatalogFor(room).Find(entry.EffectCode)!.FamilyStrength))
                .FirstOrDefault(entry => Math.Abs(entry.MagnitudeSnapshot ?? CatalogFor(room).Find(entry.EffectCode)!.FamilyStrength) > Math.Abs(magnitudeSnapshot ?? definition.FamilyStrength));
            if (definition.FamilyRefresh == BattleStatusFamilyRefresh.KeepStronger && stronger is not null)
            {
                CaptureStatus(room, stronger, BattleStatusChange.Retained, stronger.Stacks, stronger.Stacks);
                return true;
            }
            RemoveStates(room, family.Where(entry => entry.EffectCode != definition.Code), BattleStatusChange.Removed);
        }

        var loaded = SettlementStates(room);
        var effect = (loaded ?? db.BattleStatusEffects.Local.ToList()).FirstOrDefault(entry => entry.RoomId == room.Id &&
            entry.RunSequence == room.RunSequence && entry.TargetType == targetType && entry.TargetId == targetId &&
            entry.EffectCode == definition.Code);
        if (effect is null && loaded is null)
            effect = await db.BattleStatusEffects.SingleOrDefaultAsync(entry => entry.RoomId == room.Id &&
                entry.RunSequence == room.RunSequence && entry.TargetType == targetType && entry.TargetId == targetId &&
                entry.EffectCode == definition.Code);
        var active = effect is not null && db.Entry(effect).State != EntityState.Deleted &&
            effect.ExpiresAfterRound >= room.RoundNumber;
        var countBefore = active ? effect!.Stacks : 0;
        if (effect is not null && db.Entry(effect).State == EntityState.Deleted)
            db.Entry(effect).State = EntityState.Modified;
        if (effect is null)
        {
            effect = new BattleStatusEffect { RoomId = room.Id, RunSequence = room.RunSequence,
                TargetType = targetType, TargetId = targetId, EffectCode = definition.Code,
                AppliedRound = room.RoundNumber, Stacks = definition.InitialStacks };
            db.BattleStatusEffects.Add(effect);
        }
        else
        {
            if (!active || definition.CounterKind == BattleStatusCounterKind.Charges) effect.Stacks = definition.InitialStacks;
            else if (definition.Stacking == "AddStack") effect.Stacks = Math.Min(definition.MaxStacks, effect.Stacks + 1);
            // Refreshing an existing periodic effect must not postpone its due tick.
            if (!active || definition.EffectType is not ("DamageOverTime" or "HealOverTime"))
                effect.AppliedRound = room.RoundNumber;
        }
        if (counterCount.HasValue) effect.Stacks = counterCount.Value;
        var updateSource = !active || definition.EffectType is not ("DamageOverTime" or "HealOverTime") ||
            !effect.PerTickValue.HasValue;
        if (!active) effect.PerTickValue = perTickValue;
        else if (perTickValue.HasValue && definition.EffectType is "DamageOverTime" or "HealOverTime")
        {
            var oldPower = effect.PerTickValue ??
                Math.Max(1, (int)decimal.Floor(Math.Abs(definition.ValuePerStack) * effect.Stacks));
            updateSource = definition.SnapshotRefresh == BattleStatusSnapshotRefresh.Replace || perTickValue.Value >= oldPower;
            effect.PerTickValue = definition.SnapshotRefresh == BattleStatusSnapshotRefresh.Replace
                ? perTickValue.Value : Math.Max(oldPower, perTickValue.Value);
        }
        if (!active) effect.MagnitudeSnapshot = magnitudeSnapshot;
        else if (magnitudeSnapshot.HasValue)
        {
            var previous = effect.MagnitudeSnapshot ?? definition.ValuePerStack;
            updateSource = definition.SnapshotRefresh == BattleStatusSnapshotRefresh.Replace || magnitudeSnapshot.Value >= previous;
            effect.MagnitudeSnapshot = definition.SnapshotRefresh == BattleStatusSnapshotRefresh.Replace
                ? magnitudeSnapshot.Value : Math.Max(previous, magnitudeSnapshot.Value);
        }
        effect.Lifetime = definition.Lifetime == BattleStatusLifetime.Rounds && durationRounds == 0
            ? BattleStatusLifetime.CurrentRound : definition.Lifetime;
        var expiry = effect.Lifetime switch
        {
            BattleStatusLifetime.CurrentRound => room.RoundNumber,
            BattleStatusLifetime.Rounds => checked(room.RoundNumber + durationRounds),
            _ => int.MaxValue
        };
        effect.ExpiresAfterRound = active && definition.EffectType is "DamageOverTime" or "HealOverTime"
            ? Math.Max(effect.ExpiresAfterRound, expiry) : expiry;
        if (updateSource)
        {
            effect.SourceActorType = source?.ActorType;
            effect.SourceActorId = source?.ActorId;
            effect.SourceSkillCode = source?.SkillCode;
        }
        effect.BoundTargetType = boundTargetType;
        effect.BoundTargetId = boundTargetId;
        CaptureStatus(room, effect, active ? BattleStatusChange.Refreshed : BattleStatusChange.Added, countBefore, effect.Stacks);
        logs.Add($"{targetLabel} 获得 {definition.Name}，持续 {durationRounds} 回合{(effect.Stacks > 1 ? $"（{effect.Stacks} 层）" : "")}。");
        return true;
    }

    public async Task<BattleStatusEffect> SetCounterAsync(Room room, string targetType, int targetId,
        string code, int count, BattleStatusSource? source = null,
        string? boundTargetType = null, int? boundTargetId = null)
    {
        await PrepareAsync(room);
        var definition = CatalogFor(room).Find(code) ?? throw new InvalidOperationException($"Missing battle status: {code}");
        if (count < 1 || count > definition.MaxStacks) throw new ArgumentOutOfRangeException(nameof(count));
        await ApplyAsync(room, targetType, targetId, code, 0, [], string.Empty,
            source: source, boundTargetType: boundTargetType, boundTargetId: boundTargetId, counterCount: count);
        var effect = (await GetActiveAsync(room, targetType, [targetId])).Single(entry => entry.EffectCode == code);
        return effect;
    }

    public async Task<int> ConsumeAsync(Room room, string targetType, int targetId, string code, int count = int.MaxValue)
    {
        if (count <= 0) throw new ArgumentOutOfRangeException(nameof(count));
        var effect = (await GetActiveAsync(room, targetType, [targetId])).FirstOrDefault(entry => entry.EffectCode == code);
        if (effect is null) return 0;
        var before = effect.Stacks;
        var consumed = Math.Min(count, before);
        if (consumed == effect.Stacks) db.BattleStatusEffects.Remove(effect);
        else effect.Stacks -= consumed;
        CaptureStatus(room, effect, BattleStatusChange.Consumed, before, before - consumed);
        return consumed;
    }

    public async Task<int> AmplifyDamageAsync(Room room, int monsterId, int damage)
    {
        if (damage <= 0) return damage;
        var amplification = await MechanicPowerAsync(room, "Monster", monsterId, BattleStatusMechanic.HunterVulnerability);
        amplification += await ModifierAsync(room, "Monster", monsterId, "DamageTakenPercent");
        return amplification == 0 ? damage : (int)Math.Min(int.MaxValue,
            decimal.Floor(damage * (1m + amplification / 100m)));
    }

    public async Task ResolveEndOfRoundAsync(Room room, Monster monster,
        IReadOnlyList<BattleParticipant> participants, List<string> logs,
        IReadOnlyDictionary<int, OperationPotionBonuses>? operationBonuses = null,
        bool healingOnly = false)
    {
        await PrepareAsync(room);
        var effects = SettlementStates(room)?.ToList() ?? await db.BattleStatusEffects.Where(effect =>
            effect.RoomId == room.Id && effect.RunSequence == room.RunSequence).ToListAsync();
        effects.RemoveAll(effect => db.Entry(effect).State == EntityState.Deleted);
        foreach (var local in db.BattleStatusEffects.Local.Where(effect => effect.RoomId == room.Id &&
                     effect.RunSequence == room.RunSequence && db.Entry(effect).State != EntityState.Deleted))
            if (!effects.Contains(local)) effects.Add(local);
        foreach (var effect in effects.Where(effect => effect.AppliedRound < room.RoundNumber &&
                     effect.ExpiresAfterRound >= room.RoundNumber))
        {
            var definition = CatalogFor(room).Find(effect.EffectCode);
            if (definition?.Mechanic == BattleStatusMechanic.PlaguePoison) continue;
            if (healingOnly && definition?.EffectType != "HealOverTime") continue;
            if (definition?.EffectType == "HealOverTime")
            {
                BattleActor? target = effect.TargetType == "Monster" && effect.TargetId == monster.Id
                    ? BattleActor.ForMonster(monster)
                    : effect.TargetType == "Character" && participants.SingleOrDefault(entry => entry.Character.Id == effect.TargetId) is { } participant
                        ? BattleActor.ForCharacter(participant) : null;
                if (target is null || target.Hp <= 0) continue;
                var healing = Math.Max(1, effect.PerTickValue ??
                    (int)decimal.Floor(Math.Abs(definition.ValuePerStack) * effect.Stacks));
                var hpBefore = target.Hp;
                var restored = BattleDamageService.RestoreHp(target, healing);
                using var healingAction = Events.ActionScope(Source(effect), definition.Name, BattleActionKind.Periodic);
                Events.Hp(room, BattleEventKind.Heal, null, target, healing, restored, hpBefore);
                if (restored <= 0) continue;
                logs.Add($"{target.Label} 受到 {definition.Name} 治疗，恢复 {restored} 点生命。");
                continue;
            }
            if (definition?.EffectType != "DamageOverTime") continue;
            var damage = Math.Max(1, effect.PerTickValue ??
                (int)decimal.Floor(Math.Abs(definition.ValuePerStack) * effect.Stacks));
            if (effect.TargetType == "Character")
            {
                var target = participants.SingleOrDefault(entry => entry.Character.Id == effect.TargetId);
                if (target is null || target.Character.Hp <= 0) continue;
                var taken = operationBonuses?.GetValueOrDefault(target.Character.Id).DamageTakenPercent ?? 0;
                damage = Math.Max(1, (int)decimal.Floor(damage * (1m + taken / 100m)));
                var hpBefore = target.Character.Hp;
                target.Character.Hp = Math.Max(0, target.Character.Hp - damage);
                using var damageAction = Events.ActionScope(Source(effect), definition.Name, BattleActionKind.Periodic);
                Events.Hp(room, BattleEventKind.Damage, null, BattleActor.ForCharacter(target), damage, hpBefore - target.Character.Hp, hpBefore);
                logs.Add($"{target.Slot.SlotIndex}号位 {target.Character.Name} 受到 {definition.Name} 造成的 {damage} 点伤害。");
            }
            else if (effect.TargetType == "Monster" && effect.TargetId == monster.Id && monster.Hp > 0)
            {
                damage = await AmplifyDamageAsync(room, monster.Id, damage);
                var hpBefore = monster.Hp;
                monster.Hp = Math.Max(0, monster.Hp - damage);
                using var damageAction = Events.ActionScope(Source(effect), definition.Name, BattleActionKind.Periodic);
                Events.Hp(room, BattleEventKind.Damage, null, BattleActor.ForMonster(monster), damage, hpBefore - monster.Hp, hpBefore);
                logs.Add($"{monster.Name} 受到 {definition.Name} 造成的 {damage} 点伤害。");
            }
        }

        // The plague phase must keep its final-round poison until after that round's tick.
        RemoveStates(room, effects.Where(effect => effect.ExpiresAfterRound <= room.RoundNumber &&
            CatalogFor(room).Find(effect.EffectCode)?.Mechanic != BattleStatusMechanic.PlaguePoison), BattleStatusChange.Expired);
    }

    public async Task ClearRunAsync(Room room)
    {
        await PrepareAsync(room);
        var effects = SettlementStates(room)?.ToList() ?? await db.BattleStatusEffects.Where(effect => effect.RoomId == room.Id && effect.RunSequence == room.RunSequence).ToListAsync();
        effects.AddRange(db.BattleStatusEffects.Local.Where(effect => effect.RoomId == room.Id && effect.RunSequence == room.RunSequence && !effects.Contains(effect)));
        RemoveStates(room, effects, BattleStatusChange.Removed);
    }

    public async Task RemoveBoundToAsync(int roomId, string actorType, int actorId)
    {
        var effects = await db.BattleStatusEffects.Where(effect => effect.RoomId == roomId &&
            (effect.TargetType == actorType && effect.TargetId == actorId ||
             effect.BoundTargetType == actorType && effect.BoundTargetId == actorId)).ToListAsync();
        effects.AddRange(db.BattleStatusEffects.Local.Where(effect => effect.RoomId == roomId &&
            (effect.TargetType == actorType && effect.TargetId == actorId ||
             effect.BoundTargetType == actorType && effect.BoundTargetId == actorId) && !effects.Contains(effect)));
        foreach (var effect in effects.Where(effect => db.Entry(effect).State != EntityState.Deleted))
        {
            var room = db.Rooms.Local.FirstOrDefault(entry => entry.Id == roomId);
            if (room is not null)
            {
                await PrepareAsync(room);
                CaptureStatus(room, effect, BattleStatusChange.Removed, effect.Stacks, 0);
            }
            db.BattleStatusEffects.Remove(effect);
        }
    }

    public async Task<List<BattleStatusEffectResponse>> DescribeAsync(Room room, string targetType, int targetId)
    {
        var responses = await DescribeManyAsync(room, targetType, [targetId]);
        return responses.GetValueOrDefault(targetId) ?? [];
    }

    public async Task<Dictionary<int, List<BattleStatusEffectResponse>>> DescribeManyAsync(Room room, string targetType,
        IReadOnlyCollection<int> targetIds)
    {
        var effects = await GetActiveAsync(room, targetType, targetIds);
        var monsterIds = effects.Where(effect => effect.BoundTargetType == "Monster" && effect.BoundTargetId.HasValue)
            .Select(effect => effect.BoundTargetId!.Value).Distinct().ToList();
        var names = ReadSnapshot(room)?.MonsterNames ?? (monsterIds.Count == 0 ? new Dictionary<int, string>() :
            await db.Monsters.Where(monster => monsterIds.Contains(monster.Id))
                .Select(monster => new { monster.Id, monster.Name })
                .ToDictionaryAsync(monster => monster.Id, monster => monster.Name));
        var byTarget = effects.ToLookup(effect => effect.TargetId);
        return targetIds.Distinct().ToDictionary(id => id, id => byTarget[id].OrderBy(effect => effect.Id)
            .Select(effect => Snapshot(room, effect, room.RoundNumber,
                effect.BoundTargetType == "Monster" && effect.BoundTargetId is int boundId ? names.GetValueOrDefault(boundId) : null)?.ToResponse())
            .OfType<BattleStatusEffectResponse>().ToList());
    }

    private static BattleStatusSource? Source(BattleStatusEffect effect) => effect.SourceActorType is { } type && effect.SourceActorId is { } id
        ? new(type, id, effect.SourceSkillCode) : null;

    private void RemoveStates(Room room, IEnumerable<BattleStatusEffect> effects, BattleStatusChange reason)
    {
        foreach (var effect in effects.Where(effect => db.Entry(effect).State != EntityState.Deleted).ToList())
        {
            CaptureStatus(room, effect, reason, effect.Stacks, 0);
            db.BattleStatusEffects.Remove(effect);
        }
    }

    private void CaptureStatus(Room room, BattleStatusEffect effect, BattleStatusChange change, int before, int after,
        BattleEventKind kind = BattleEventKind.Status)
    {
        if (Snapshot(room, effect, room.RoundNumber, Events.ActorName(effect.BoundTargetType, effect.BoundTargetId)) is { } snapshot)
            Events.Status(room, effect.TargetType, effect.TargetId, snapshot, change, before, after, kind);
    }

    private BattleStatusSnapshot? Snapshot(Room room, BattleStatusEffect effect, int round, string? boundName = null)
    {
        var definition = CatalogFor(room).Find(effect.EffectCode);
        if (definition is null || definition.IsHidden) return null;
        var rounds = effect.Lifetime == BattleStatusLifetime.Rounds
            ? (int)Math.Clamp((long)effect.ExpiresAfterRound - round + 1, 0, int.MaxValue) : 0;
        var duration = effect.Lifetime switch
        {
            BattleStatusLifetime.UntilConsumed => "消耗后移除，挑战结束时清空",
            BattleStatusLifetime.Encounter => "当前目标死亡或挑战结束时清空",
            BattleStatusLifetime.Run => "本次挑战持续",
            BattleStatusLifetime.CurrentRound => "本回合有效",
            _ => $"剩余 {rounds} 回合"
        };
        if (effect.BoundTargetId.HasValue && effect.Lifetime == BattleStatusLifetime.Rounds)
            duration += "，绑定目标死亡时清空";
        return new()
        {
            Code = effect.EffectCode, Name = definition.Name, EffectType = definition.EffectType,
            Description = definition.Mechanic switch
            {
                BattleStatusMechanic.Guard when effect.MagnitudeSnapshot.HasValue => $"本回合受到的直接伤害降低 {effect.MagnitudeSnapshot:0.##}%。",
                BattleStatusMechanic.NormalAttackEcho => $"下次普通攻击附加 {effect.MagnitudeSnapshot ?? definition.FamilyStrength:0.##}% 追击；消费后移除。",
                _ => _mechanicDescriptions.Status(definition, effect.MagnitudeSnapshot)
            },
            IsPositive = definition.IsPositive, CanDispel = definition.IsDispellable, Stacks = effect.Stacks,
            RemainingRounds = rounds, Lifetime = effect.Lifetime, CounterKind = definition.CounterKind, Mechanic = definition.Mechanic,
            AppliedRound = effect.AppliedRound, ExpiresAfterRound = effect.ExpiresAfterRound, PerTickValue = effect.PerTickValue,
            MagnitudeSnapshot = effect.MagnitudeSnapshot, DurationText = duration,
            CounterText = definition.CounterKind switch
            {
                BattleStatusCounterKind.Charges => $"剩余 {effect.Stacks} 次",
                BattleStatusCounterKind.Stacks => $"{effect.Stacks} 层",
                _ => string.Empty
            },
            SourceActorType = effect.SourceActorType, SourceActorId = effect.SourceActorId, SourceSkillCode = effect.SourceSkillCode,
            BoundTargetType = effect.BoundTargetType, BoundTargetId = effect.BoundTargetId, BoundTargetName = boundName
        };
    }
}

