const definitions=new Map(cfg.MonsterCombat.StatusEffects.map(s=>[s.Code,s]));
const skillSpec={'dark-deep-lv1-spider-stab':[2,4],'dark-deep-lv1-stalker-fang':[2,4],
 'dark-deep-lv1-guard-smash':[2,4],'dark-deep-lv1-weaver-thread':[4,6],
 'dark-deep-lv1-matriarch-fang':[2,4],'dark-deep-lv1-matriarch-mist':[4,6]};
module.exports=function audit(s,route){
 const starts={},minimum=Array(5).fill(100),basicStates=new Map(),phaseFacts=s.MonsterPhaseRounds.filter(p=>p.MonsterId===5);
 const last=phaseFacts.at(-1),threshold=Math.ceil(s.InitialMonsters[4].MaxHp*.04),original=s.Builds[0].Stats.MaxHp;
 let active=false,start=null,end=null,target=null,layers=0,unit=0,progress=0,method=null,rewardStart=null,rewardEnd=null,erosionStacks=0;
 let poisonTicks=0,poisonDamage=0,basicTicks=0,basicDamage=0,basicCleanses=0,rewardApplied=0,lethals=0,targetDead=false;
 const growth=[],ticks=[],rewardRounds=[],erosions=[],cooldownMisses=[];
 assert.equal(s.SoftEnrageCasts,0);assert.equal(s.HardEnrageCasts,0);assert.equal(s.PotionsUsed,0);
 assert.deepEqual(s.InitialMonsters.map(m=>[m.Wave,m.Position]),[[1,1],[2,1],[3,1],[4,1],[5,1]]);
 assert(s.InitialMonsters.every(m=>m.Defense===0));
 for(const[ti,t]of s.RoundTrace.entries()){
  const r=t.Data.RoundNumber-1,committed=new Set();let tickThisRound=false;
  assert(t.Data.OperationPotions.every(p=>!p.ItemCode));assert.equal(t.Data.ConsumableBuffs.length,0);
  for(const e of t.Data.Events){
   if(starts[e.Monster]===undefined)starts[e.Monster]=r;
   if(e.Target?.startsWith('character:')&&e.HpAfter!==null&&e.TargetMaxHp>0){
    const i=+e.Target.split(':')[1]-1;
    minimum[i]=Math.min(minimum[i],100*e.HpAfter/e.TargetMaxHp);
    const cap=e.Target===target?Math.floor(original*(1-erosionStacks*.1)):s.Builds[i].Stats.MaxHp;
    assert.equal(e.TargetMaxHp,cap,'Live max HP during damage/healing');
    if(e.Target===target&&e.HpAfter===0)targetDead=true;
   }
   assert(!e.SkillCode?.startsWith('depth-placeholder-')&&!e.SkillCode?.startsWith('endgame-')&&!e.SkillCode?.startsWith('widow-'));
   assert.notEqual(e.ActionKind,2,'No soul imprint');
   if(e.Kind===0&&e.ActionKind===0&&e.Source?.startsWith('monster:')){
    const spec=skillSpec[e.SkillCode];assert(spec);assert(r-starts[e.Source]+1>=spec[0]);
    const key=e.Source+e.SkillCode;if(!committed.has(key)){
     const prior=s.RoundTrace[ti-1]?.Data.MonsterCooldowns.find(c=>c.Actor===e.Source&&c.SkillCode===e.SkillCode);
     if(prior)assert(r>=prior.ReadyAtRound);
     assert.equal(t.Data.MonsterCooldowns.find(c=>c.Actor===e.Source&&c.SkillCode===e.SkillCode)?.ReadyAtRound,r+spec[1]);committed.add(key);
    }
   }
   if(e.Status?.Code===plague){
    const st=e.Status;assert(st.CanDispel&&!st.IsPositive);assert.equal(st.Lifetime,0);assert.equal(st.BoundTarget,boss);
    if(e.StatusChange===0){
     assert.equal(start,null);assert.equal(st.Stacks,1);assert.equal(st.AppliedRound,r);assert.equal(st.ExpiresAfterRound,r+3);
     const prior=s.RoundTrace[ti-1].Data;
     assert(prior.Monsters.find(m=>m.Actor===boss).Hp<=s.InitialMonsters[4].MaxHp*.7,'Next full round after committed HP crossing');
     const modifiers=prior.Statuses.filter(st=>st.Target===boss&&st.ExpiresAfterRound>=r).reduce((n,st)=>{
      const d=definitions.get(st.EffectCode);return n+(d?.EffectType==='AttackPercent'?(st.MagnitudeSnapshot??d.ValuePerStack)*st.Stacks:0);},0);
     assert.equal(st.PerTickValue,Math.max(1,Math.floor(s.InitialMonsters[4].Attack*Math.max(0,1+modifiers/100)*.1)));
     active=true;start=r;target=e.Target;layers=1;unit=st.PerTickValue;progress=0;assert.equal(target,'character:1');
    }else if(e.StatusChange===1){
     assert(active&&tickThisRound);assert.equal(st.AppliedRound,start);assert.equal(st.ExpiresAfterRound,start+3);
     assert.equal(st.PerTickValue,unit);assert.equal(st.Stacks,layers+1);assert.equal(st.Stacks,r-start+2);
     layers=st.Stacks;growth.push({Round:r,Stacks:layers});
    }else if(e.StatusChange===3){
     assert(active);assert.equal(e.Target,target);end=r;
     if(e.Kind===3){assert.equal(e.SkillCode,'acolyte-purify');method='Cleanse';}
     else if(e.Source?.startsWith('character:')){assert(progress>=threshold);method='LightDamage';}
     else if(lethals){assert.equal(r,start+3);assert(tickThisRound);method='LethalStacks';}
     else if(targetDead)method='TargetDeath';
     else{assert.equal(t.Data.Monsters.find(m=>m.Actor===boss)?.Hp,0);method='BossDeath';}
     active=false;
    }
   }
   if(e.Status?.Code===erosion){
    const st=e.Status;assert(!st.CanDispel&&!st.IsPositive);assert.equal(st.Lifetime,2);assert.equal(st.MagnitudeSnapshot,original);
    assert.equal(st.BoundTarget,boss);assert.equal(e.Target,target);assert([1,2].includes(st.Stacks));
    if([0,1].includes(e.StatusChange)){
     assert(active&&tickThisRound);assert.equal(layers,st.Stacks+2);erosionStacks=st.Stacks;
     erosions.push({Round:r,PoisonStacks:layers,ErosionStacks:erosionStacks,MaxHp:Math.floor(original*(1-erosionStacks*.1))});
    }else if(e.StatusChange===3){assert(!active);erosionStacks=0;}
   }
   if(active&&e.Kind===0&&e.Source?.startsWith('character:')&&e.Target===boss&&e.Element===4&&e.ActualAmount>0&&[0,1,3,4,6].includes(e.ActionKind))progress+=e.ActualAmount;
   if(e.Kind===0&&e.ActionKind===5&&e.SkillCode==='plague-poison-tick'){
    assert(active&&!tickThisRound);assert.equal(e.Target,target);assert.equal(e.Source,boss);
    assert.equal(layers,r-start+1);assert.equal(e.CalculatedAmount,unit*layers);assert.equal(e.ActualAmount,Math.min(e.HpBefore,unit*layers));
    assert(!e.IsCritical&&e.Element===null&&e.ElementModifier===0);tickThisRound=true;poisonTicks++;poisonDamage+=e.ActualAmount;
    ticks.push({Round:r,Stacks:layers,Damage:e.ActualAmount});
   }
   if(e.Kind===0&&e.SkillCode==='plague-poison-lethal'){
    assert(active&&tickThisRound);assert.equal(layers,5);assert.equal(r,start+3);assert.equal(e.ActionKind,6);
    assert.equal(e.Target,target);assert.equal(e.ActualAmount,e.HpBefore);assert.equal(e.CalculatedAmount,e.HpBefore);assert.equal(e.HpAfter,0);
    assert(!e.IsCritical&&e.Element===null&&e.ElementModifier===0);lethals++;
   }
   if(e.Status?.Code===reward&&e.StatusChange===0){
    assert(!active&&['Cleanse','LightDamage'].includes(method));assert.equal(e.Target,target);assert.equal(r,end+1);assert.equal(e.Status.ExpiresAfterRound,r+2);
    assert(e.Status.IsPositive&&!e.Status.CanDispel);assert.equal(e.Status.BoundTarget,boss);rewardStart=r;rewardEnd=r+2;rewardApplied++;
   }
   if(e.Status?.Code===basic){
    const st=e.Status;assert.equal(st.Stacks,1);
    if([0,1].includes(e.StatusChange)){
     if(st.Source===boss&&e.Target===target)assert(!active&&!(rewardStart!==null&&r>=rewardStart&&r<=rewardEnd),'Basic poison suppressed on phase/reward target');
     assert.equal(st.ExpiresAfterRound,r+2);
     if(e.StatusChange===0)assert.equal(st.AppliedRound,r);
     else if(basicStates.has(e.Target)){const old=basicStates.get(e.Target);assert.equal(st.AppliedRound,old.AppliedRound);assert(st.PerTickValue>=old.PerTickValue);}
     basicStates.set(e.Target,st);
    }else if([3,4].includes(e.StatusChange)){if(e.Kind===3)basicCleanses++;basicStates.delete(e.Target);}
   }
   if(e.Kind===0&&e.ActionKind===5&&e.Source?.startsWith('monster:')&&e.SkillCode!=='plague-poison-tick'){
    const st=basicStates.get(e.Target);assert(st);assert(r>st.AppliedRound&&r<=st.ExpiresAfterRound);
    assert.equal(e.CalculatedAmount,st.PerTickValue);assert.equal(e.ActualAmount,Math.min(e.HpBefore,st.PerTickValue));
    assert(!e.IsCritical&&e.Element===null);basicTicks++;basicDamage+=e.ActualAmount;
   }
  }
  const states=t.Data.Statuses;
  for(const c of t.Data.Characters){
   const i=+c.Actor.split(':')[1]-1,st=states.find(st=>st.Target===c.Actor&&st.EffectCode===erosion);
   assert.equal(c.MaxHp,Math.floor(s.Builds[i].Stats.MaxHp*(1-(st?.Stacks??0)*.1)),'Persisted cap equals original maximum, never compounds');
   assert(c.Hp<=c.MaxHp);
  }
  for(const key of basicStates.keys())if(!states.some(st=>st.Target===key&&st.EffectCode===basic))basicStates.delete(key);
  if(start!==null&&t.Data.Events.some(e=>e.Monster===boss)){
   const p=phaseFacts.find(p=>p.LocalRound===r-starts[boss]+1);assert(p);assert.equal(p.Activations,1);assert.equal(p.WaterDamage,progress);
   assert.equal(p.IsActive,active);
   if(rewardStart!==null&&r>=rewardStart&&r<=rewardEnd)rewardRounds.push(r);
  }
  if(route==='cleanse-only'&&start!==null&&r>=start&&r<=start+3){
   const cd=t.Data.CharacterCooldowns.find(c=>c.Actor==='character:2'&&c.SkillCode==='acolyte-purify');
   cooldownMisses.push({Round:r,ReadyAtRound:cd?.ReadyAtRound??null});
  }
 }
 assert.equal(last.Activations,1);assert(!active);assert.equal(last.WaterDamage,progress);
 assert.equal(last.LastActivationRound,start);assert.equal(last.Breaks,['Cleanse','LightDamage'].includes(method)?1:0);
 assert.equal(last.Expiries,0);assert.equal(last.LastExpiryRound,null);assert.equal(last.LinkedHits,lethals);assert.equal(erosionStacks,0);
 if(method==='LethalStacks'){assert.equal(poisonTicks,4);assert.equal(poisonDamage,10*unit);assert.equal(lethals,1);assert.equal(rewardApplied,0);}
 else if(['Cleanse','LightDamage'].includes(method)){
  assert.equal(last.LastBreakRound,end);assert.equal(rewardApplied,1);assert.deepEqual(rewardRounds,[end+1,end+2,end+3]);
 }else{assert.equal(rewardApplied,0);assert.equal(lethals,0);}
 if(['unhandled','single-light'].includes(route)){assert(['TargetDeath','LethalStacks'].includes(method));assert(progress<threshold);}
 if(route==='cleanse-only'){
  assert(['Cleanse','LethalStacks','TargetDeath'].includes(method));
  if(method!=='Cleanse')for(const cd of cooldownMisses)assert(cd.ReadyAtRound>cd.Round,'Failed cleanse route used actual cooldowns');
 }
 if(route==='light-only')assert.equal(method,'LightDamage');
 if(route==='main')assert(['Cleanse','LightDamage'].includes(method));
 return {MinimumHpPercentBySlot:minimum,StartRound:start,EndRound:end,WindowRoundAtEnd:end-start+1,Method:method,
  ActualLightDamage:progress,RequiredLightDamage:threshold,AttackSnapshotPerStack:unit,PoisonTicks:poisonTicks,PoisonDamage:poisonDamage,
  Growth:growth,Ticks:ticks,Erosion:erosions,LethalDeaths:lethals,RewardRounds:rewardRounds,
  BasicPoisonTicks:basicTicks,BasicPoisonDamage:basicDamage,BasicPoisonCleanses:basicCleanses,CleanseCooldownRounds:cooldownMisses,
  LiveMaximumLifeVerified:true,SnapshotGrowthAndFourFullRoundWindowVerified:true,RewardThreeFullRoundsVerified:rewardApplied===1,
  BasicPoisonSuppressionVerified:true,SkillCooldownsVerified:true};
};
if(require.main===module)for(const n of ['main','light-only','cleanse-only','single-light','unhandled']){
 const j=JSON.parse(fs.readFileSync(__dirname+'/final-'+n+'.json')),a=j.Samples.map(s=>module.exports(s,n));
 console.log(JSON.stringify({Scenario:n,Runs:a.length,Methods:a.reduce((m,x)=>(m[x.Method]=(m[x.Method]??0)+1,m),{}),
  Windows:a.reduce((m,x)=>(m[x.WindowRoundAtEnd]=(m[x.WindowRoundAtEnd]??0)+1,m),{}),MinTank:Math.min(...a.map(x=>x.MinimumHpPercentBySlot[0]))}));
}
